  const bead = new THREE.Mesh(new THREE.SphereGeometry(0.05, 20, 14), new THREE.MeshBasicMaterial({ color: new THREE.Color(c.color).lerp(new THREE.Color("#ffffff"), 0.45), toneMapped: false })); g.add(bead);
