      if (!order) order = Object.keys(v).sort((a, b) => v[a] - v[b]);
      for (const k in v) if (!order.includes(k)) { order.push(k); order.sort((a, b) => v[a] - v[b]); }
      if (t - last >= 1.0) for (let j = 0; j + 1 < order.length; j++) if (v[order[j]] > v[order[j + 1]] * 1.025) { [order[j], order[j + 1]] = [order[j + 1], order[j]]; last = t; break; }
      g.order = order.slice();
