// ============================================================ 4 · pódio (48–55)
// Back in the vault: the pedestals rise to how many times each currency rose against the real (true scale),
// the "?" plates fold away and the % plates pop in, the franc last. Reveal over the podium, then push onto
// the franc while the headline says +799%.
const POD_RISE = { EUR: 48.1, GBP: 48.45, USD: 48.8, CHF: 48.95 }, POD_PCT = { EUR: 49.25, GBP: 49.6, USD: 0, CHF: 50.6 };
function podiumAnim(peds, t) {
  for (const p of peds) {
    const k = eOut(lin(t, POD_RISE[p.key], POD_RISE[p.key] + (p.key === "CHF" ? 1.6 : 1.1)));
    p.setH(lerp(PED_H0, p.final, k));
    if (!POD_PCT[p.key]) { p.showQ(0); p.showPct(1); continue; }   // the dollar's plate is already up since the hook
    p.showQ(1 - sm(t, POD_RISE[p.key], POD_RISE[p.key] + 0.25)); p.showPct(pop(t, POD_PCT[p.key], 0.35));
  }
}
addScene("podio", 48.0, 55.0, (S) => {
  const v = fxVault(S, 6);
  const peds = buildPedestals(S), chf = peds.find((p) => p.key === "CHF");
  const shaft = makeLightShaft([chf.group.position.x, 5.1, PED_Z], [chf.group.position.x, 0.05, PED_Z + 0.2], { w0: 0.3, w1: 1.4, color: "#ffd38a", opacity: 0.24 }); S.backdrop(shaft.group);
  const anim = (t) => {
    v.update(t); v.room.beacon(0); v.room.lights(1.1 + 0.2 * beat(t, 48.0, 0.8) + 0.25 * beat(t, 53.0, 2.0));
    podiumAnim(peds, t); peds.forEach((p, i) => p.coin.spin(0.3 * Math.sin(t * 0.9 + i * 1.4)));
    shaft.set(sm(t, 50.6, 51.2));
  };
  peds.forEach((p) => { S.hero(p.group, "pedestal " + FX[p.key].short.toLowerCase(), p.key === "CHF" ? {} : { when: (t) => t < 51.4 }); S.solid(p.group, "pedestal " + p.key); });
  const all = envelope(peds.map((p) => p.group), anim, 48.0, 51.4);
  const one = envelope([chf.group], anim, 51.4, 55.0);
  return (t) => {
    anim(t); vaultLight(t, t > 51.4 ? chf.group.position.x : 0, 1.2);
    const R = (k) => CAM.move(all, "reveal", k, { zone: "stage", from: [-0.2, 0.18, 1], pull: 1.0, pull0: 1.1 });
    const P = CAM.move(one, "push", lin(t, 51.4, 55.0), { zone: "stage", from: [-0.25, 0.16, 1], pull: 1.02, pull0: 1.3 });
    CAM.apply(t < 51.4 ? R(lin(t, 48.0, 51.4)) : CAM.blend(R(1), P, sm(t, 51.4, 52.1)));
  };
});

// ============================================================ 5 · pergunta (55–60)
// "Você acertou a moeda que mais subiu?" The finished podium; the camera swings round it (orbit).
addScene("pergunta", 55.0, 60.0, (S) => {
  const v = fxVault(S, 6);
  const peds = buildPedestals(S), chf = peds.find((p) => p.key === "CHF");
  const shaft = makeLightShaft([chf.group.position.x, 5.1, PED_Z], [chf.group.position.x, 0.05, PED_Z + 0.2], { w0: 0.3, w1: 1.4, color: "#ffd38a", opacity: 0.24 }); S.backdrop(shaft.group);
  const anim = (t) => { v.update(t); v.room.beacon(0); v.room.lights(1.1); podiumAnim(peds, 60); peds.forEach((p, i) => p.coin.spin(0.3 * Math.sin(t * 0.9 + i * 1.4))); shaft.set(1); };
  peds.forEach((p) => { S.hero(p.group, "pedestal " + FX[p.key].short.toLowerCase()); S.solid(p.group, "pedestal " + p.key); });
  const box = envelope(peds.map((p) => p.group), anim, 55.0, 60.0);
  return (t) => {
    anim(t); vaultLight(t, 0, 1.1);
    CAM.apply(CAM.move(box, "orbit", lin(t, 55.0, 60.0), { zone: "stage", from: [-0.12, 0.22, 1], deg: 30, pull: 1.02 }));
  };
});
